[CmdletBinding()]
param([string]$RepositoryRoot,[string]$ReaderDirectory,[Parameter(Mandatory=$true)][string]$OutputDirectory)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
if(-not$RepositoryRoot){$RepositoryRoot=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../..'))}
if(-not$ReaderDirectory){$ReaderDirectory=Join-Path $RepositoryRoot 'scripts/runtime'}
if(Test-Path -LiteralPath $OutputDirectory){throw 'Preserve prior debt reader regression.'};[void][IO.Directory]::CreateDirectory($OutputDirectory)
. (Join-Path $RepositoryRoot 'scripts/runtime/RuntimeHarness.Common.ps1')
. (Join-Path $ReaderDirectory 'Chunk7CombatPersistenceEvidence.ps1')
$fixture=@(([IO.File]::ReadAllText((Join-Path $RepositoryRoot 'tests/Chunk7Diagnostics/OwnedPairsEvidenceFixtures.json'))|ConvertFrom-Json).fixtures|Where-Object name -CEQ 'persistence-load-legacy-mounted-pending-tb-manual')[0]
function Clone($x){$x|ConvertTo-Json -Depth 90|ConvertFrom-Json}
function Put($x,[string]$key,$v){$x|Add-Member -NotePropertyName $key -NotePropertyValue $v -Force}
$results=[Collections.Generic.List[object]]::new();$watch=[Diagnostics.Stopwatch]::StartNew()
function Check([string]$Name,[scriptblock]$Body,[bool]$Reject=$false){$pass=$false;$err=$null;try{&$Body;$pass=-not$Reject}catch{$err=$_.Exception.Message;$pass=$Reject};$results.Add([pscustomobject]@{name=$Name;pass=$pass;expectedRefusal=$Reject;error=$err});if(-not$pass){Write-Output ('FAIL '+$Name+': '+$err)}}
function Fresh {
 $v=Clone $fixture;$v.request.ownedPairs.case='owner-seed-checkpoint-load';$v.request.ownedPairs.expectedNativeLoadCount=1;$v.request.ownedPairs.expectedNativeWriteCount=1
 $p=$v.artifact.observations.coldRestoration
 foreach($spec in @(@('Kingmaker.EntitySystem.Entities.UnitEntityData','JoinCombat','06008355','DebtJoinBefore','DebtJoinAfter'),@('Kingmaker.Controllers.Combat.UnitCombatPrepareController','Tick','0600936F','DebtPrepareBefore','DebtPrepareAfter'))){$p.hooks+=@([pscustomobject]@{declaringType=$spec[0];method=$spec[1];token=$spec[2];moduleMvid='07fa1e4d-8618-41b3-9b8d-faa17d3b26f7';prefix=$spec[3];postfix=$spec[4]})}
 Put $p debtDiagnostics ([pscustomobject]@{contract='chunk7-native-debt-boundary-observer-v1';runId=$v.request.runId;events=@();maximumEvents=128;errors=0;dropped=0;openCalls=0;requestUnchanged=$true;complete=$true;scope='exact-schema2-cold-after-presentation';methodEntryMayBeRefusedByProductionPrefix=$true})
 $checks=@();$fields=@('Standard','Move','Swift','Initiative','Reaction','ReactionsRemaining','LastSurpriseTicks')
 for($j=0;$j-lt5;$j++){
  $a=if($j-eq4){$v.artifact.observations.nativeWrite.archive}else{$v.artifact.observations.loadedArchive};$rows=@();$states=@()
  foreach($actor in $a.Combat.Actors){$native=$actor.Native;$values=@(foreach($name in $fields){[pscustomobject]@{field=$name;saved=$native.$name;actual=$native.$name;passed=$true}});$rows+=@([pscustomobject]@{actorId=$native.Id;saved=(Clone $native);actual=(Clone $native);fields=$values;passed=$true});$states+=@([pscustomobject]@{actorId=$native.Id;inCombat=$actor.InCombat;prepared=$actor.Prepared})}
  $checks+=@([pscustomobject]@{contract='chunk7-native-combat-debt-observation-v1';phase=$(if($j-eq0){'cold-observe-before-binding'}else{'assert-combat-debt'});frame=(100+$j);gameTicks=$a.GameTimeTicks;savedGameTicks=$a.GameTimeTicks;elapsedSeconds=0.0;windowAccepted=$true;actors=$rows;passed=$true;paused=$true;archiveRestorePhase='all-pair-presentation-restored';restorationPending=$false;actorStates=$states})
 }
 Put $v.artifact.observations combatDebtChecks $checks;$v
}
function Event($v,[string]$Kind,[string]$Edge,[int]$Call){$archive=$v.artifact.observations.loadedArchive;[pscustomobject]@{kind=$Kind;edge=$Edge;callId=$Call;actorId=$(if($Kind-ceq'native-join-combat'){$archive.Combat.Actors[0].Native.Id}else{$null});frame=100;gameTicks=$archive.GameTimeTicks;paused=$false;nativePassing=$true;restorePhase='all-pair-presentation-restored';restorationPending=$false;actors=@($archive.Combat.Actors|ForEach-Object{[pscustomobject]@{native=(Clone $_.Native);inCombat=$true;prepared=$false}})}}
function Validate($v){Assert-KmcChunk7CombatRestorationProbe $v.artifact.observations.coldRestoration $v.artifact.observations.loadedArchive $v.request;Assert-KmcChunk7CombatDebtChecks $v.request $v.artifact.observations}
Check 'selected eight hooks and complete five debt comparisons with no claimed method entries' {Validate (Fresh)}
Check 'matched schema-3 control retains two exact debt snapshots and its own scope' {$v=Fresh;$v.request.persistenceCase='pending-schema3-control-manual';$v.request.ownedPairs.expectedNativeWriteCount=0;$v.artifact.observations.coldRestoration.debtDiagnostics.scope='exact-schema3-control-cold-after-presentation';$v.artifact.observations.combatDebtChecks=@($v.artifact.observations.combatDebtChecks|Select-Object -First 2);Validate $v}
Check 'schema-3 control refuses a borrowed schema-2 scope' {$v=Fresh;$v.request.persistenceCase='pending-schema3-control-manual';$v.request.ownedPairs.expectedNativeWriteCount=0;$v.artifact.observations.combatDebtChecks=@($v.artifact.observations.combatDebtChecks|Select-Object -First 2);Validate $v} $true
Check 'selected nested Join/Prepare windows pair independently' {$v=Fresh;$d=$v.artifact.observations.coldRestoration.debtDiagnostics;$d.events=@((Event $v 'native-join-combat' 'before' 1),(Event $v 'native-combat-prepare' 'before' 2),(Event $v 'native-combat-prepare' 'after' 2),(Event $v 'native-join-combat' 'after' 1));Validate $v}
Check 'unchanged legacy six-hook proof remains accepted' {$v=Clone $fixture;Assert-KmcChunk7CombatRestorationProbe $v.artifact.observations.coldRestoration $v.artifact.observations.loadedArchive $v.request;Assert-KmcChunk7CombatDebtChecks $v.request $v.artifact.observations}
foreach($fault in @('case','source-direction','current-child','load2','write0','write2','foreign-scenario')){Check ('unselected neighbor rejects borrowed eight-hook debt proof '+$fault){$v=Fresh;switch($fault){'case'{$v.request.ownedPairs.case='persistence-load'};'source-direction'{$v.request.ownedPairs.case='owner-seed-checkpoint-save'};'current-child'{$v.request.persistenceCase='owned-schema2-pending-current-manual'};'load2'{$v.request.ownedPairs.expectedNativeLoadCount=2};'write0'{$v.request.ownedPairs.expectedNativeWriteCount=0};'write2'{$v.request.ownedPairs.expectedNativeWriteCount=2};'foreign-scenario'{$v.request.scenario='chunk7-persistence-load'}};Validate $v} $true}
foreach($fault in @('missing-hook','wrong-token','wrong-native-mvid','wrong-signature-name','missing-journal','extra-journal-field','wrong-run','wrong-bound','dropped','errors','openCalls','changed-request','incomplete','unknown-event','unpaired-before','unpaired-after','duplicate-call','wrong-call-kind','foreign-actor','missing-actor','bad-actor-flag','bad-phase','empty-prepare','regressed-time')){Check ('selected boundary refuses '+$fault){$v=Fresh;$p=$v.artifact.observations.coldRestoration;$d=$p.debtDiagnostics;$d.events=@((Event $v 'native-join-combat' 'before' 1),(Event $v 'native-join-combat' 'after' 1));switch($fault){
 'missing-hook'{$p.hooks=@($p.hooks|Select-Object -First 7)};'wrong-token'{$p.hooks[6].token='06008354'};'wrong-native-mvid'{$p.hooks[6].moduleMvid=$v.request.dllMvid};'wrong-signature-name'{$p.hooks[7].prefix='PrepareBefore'};'missing-journal'{$p.PSObject.Properties.Remove('debtDiagnostics')};'extra-journal-field'{Put $d overrideAccepted $true};'wrong-run'{$d.runId='foreign'};'wrong-bound'{$d.maximumEvents=129};'dropped'{$d.dropped=1};'errors'{$d.errors=1};'openCalls'{$d.openCalls=1};'changed-request'{$d.requestUnchanged=$false};'incomplete'{$d.complete=$false};'unknown-event'{$d.events[0].kind='native-prepare'};'unpaired-before'{$d.events=@($d.events[0])};'unpaired-after'{$d.events=@($d.events[1])};'duplicate-call'{$d.events+=@((Clone $d.events[1]))};'wrong-call-kind'{$d.events[1].kind='native-combat-prepare';$d.events[1].actorId=$null};'foreign-actor'{$d.events[0].actorId='foreign'};'missing-actor'{$d.events[1].actors=@($d.events[1].actors|Select-Object -First 1)};'bad-actor-flag'{$d.events[0].actors[0].prepared='false'};'bad-phase'{$d.events[0].restorePhase='validated-before-native-mutation'};'empty-prepare'{$d.events=@((Event $v 'native-combat-prepare' 'before' 1),(Event $v 'native-combat-prepare' 'after' 1));foreach($e in $d.events){foreach($row in $e.actors){$row.prepared=$true}}};'regressed-time'{$d.events[1].frame=99}
 };Validate $v} $true}
foreach($fault in @('missing-record','extra-record','wrong-phase','wrong-saved-graph','wrong-window','wrong-field-name','wrong-field-value','missing-field','false-field','forged-success','wrong-actor-state','missing-actor','wrong-state-flag')){Check ('selected field journal refuses '+$fault){$v=Fresh;$o=$v.artifact.observations;$r=$o.combatDebtChecks[0];switch($fault){'missing-record'{$o.combatDebtChecks=@($o.combatDebtChecks|Select-Object -First 4)};'extra-record'{$o.combatDebtChecks+=@((Clone $r))};'wrong-phase'{$r.phase='after-write'};'wrong-saved-graph'{$r.actors[0].saved.Standard++};'wrong-window'{$r.gameTicks+=300000001L;$r.elapsedSeconds=30.0000001};'wrong-field-name'{$r.actors[0].fields[0].field='Refill'};'wrong-field-value'{$r.actors[0].fields[0].actual++};'missing-field'{$r.actors[0].fields=@($r.actors[0].fields|Select-Object -First 6)};'false-field'{$r.actors[0].fields[0].passed=$false};'forged-success'{$r.actors[0].actual.Standard=99;$r.actors[0].fields[0].actual=99};'wrong-actor-state'{$r.actorStates[0].actorId='foreign'};'missing-actor'{$r.actors=@($r.actors|Select-Object -First 1)};'wrong-state-flag'{$r.actorStates[0].prepared='false'}};Validate $v} $true}
Check 'old six-hook proof cannot borrow a debt journal' {$v=Clone $fixture;Put $v.artifact.observations.coldRestoration debtDiagnostics ((Fresh).artifact.observations.coldRestoration.debtDiagnostics);Assert-KmcChunk7CombatRestorationProbe $v.artifact.observations.coldRestoration $v.artifact.observations.loadedArchive $v.request} $true
Check 'old observation cannot borrow field comparisons' {$v=Clone $fixture;Put $v.artifact.observations combatDebtChecks ((Fresh).artifact.observations.combatDebtChecks);Assert-KmcChunk7CombatDebtChecks $v.request $v.artifact.observations} $true
Check 'integer surprise tick equality preserves one tick above double exact range' {$v=Fresh;$n=9007199254740992L;$v.artifact.observations.loadedArchive.Combat.Actors[0].Native.LastSurpriseTicks=$n;for($j=0;$j-lt4;$j++){$r=$v.artifact.observations.combatDebtChecks[$j];$r.actors[0].saved.LastSurpriseTicks=$n;$r.actors[0].actual.LastSurpriseTicks=$n;$r.actors[0].fields[6].saved=$n;$r.actors[0].fields[6].actual=$n};$r=$v.artifact.observations.combatDebtChecks[0];$r.actors[0].actual.LastSurpriseTicks=$n+1L;$r.actors[0].fields[6].actual=$n+1L;Assert-KmcChunk7CombatDebtChecks $v.request $v.artifact.observations} $true
Check 'integer field attribution requires actual integer tokens' {$v=Fresh;$r=$v.artifact.observations.combatDebtChecks[0];$r.actors[0].fields[5].actual=[double]$r.actors[0].actual.ReactionsRemaining;Assert-KmcChunk7CombatDebtChecks $v.request $v.artifact.observations} $true
function Clock($v,[long]$ElapsedTicks){$n=9007199254740992L;$v.artifact.observations.loadedArchive.GameTimeTicks=$n;$v.artifact.observations.nativeWrite.archive.GameTimeTicks=$n;foreach($r in $v.artifact.observations.combatDebtChecks){$r.savedGameTicks=$n;$r.gameTicks=$n+$ElapsedTicks;$r.elapsedSeconds=[double]$ElapsedTicks/10000000.0};$v}
Check 'exact thirty second window is accepted above double exact tick range' {$v=Clock (Fresh) 300000000L;Assert-KmcChunk7CombatDebtChecks $v.request $v.artifact.observations}
Check 'one tick beyond unchanged clock window is refused above double exact tick range' {$v=Clock (Fresh) 300000001L;Assert-KmcChunk7CombatDebtChecks $v.request $v.artifact.observations} $true
Check 'complete maximum 128 method events are accepted' {$v=Fresh;$d=$v.artifact.observations.coldRestoration.debtDiagnostics;$d.events=@(for($i=1;$i-le64;$i++){Event $v 'native-join-combat' 'before' $i;Event $v 'native-join-combat' 'after' $i});Validate $v}
Check '129 method events are refused without enlarging the bound' {$v=Fresh;$d=$v.artifact.observations.coldRestoration.debtDiagnostics;$d.events=@(for($i=1;$i-le64;$i++){Event $v 'native-join-combat' 'before' $i;Event $v 'native-join-combat' 'after' $i});$d.events+=@((Event $v 'native-join-combat' 'before' 65));Validate $v} $true
function FloatField($v,[string]$Name,[double]$Saved,[double]$Actual){$index=[Array]::IndexOf(@('Standard','Move','Swift','Initiative','Reaction'),$Name);$v.artifact.observations.loadedArchive.Combat.Actors[0].Native.$Name=$Saved;for($j=0;$j-lt4;$j++){$row=$v.artifact.observations.combatDebtChecks[$j].actors[0];$row.saved.$Name=$Saved;$row.actual.$Name=$Saved;$row.fields[$index].saved=$Saved;$row.fields[$index].actual=$Saved};$row=$v.artifact.observations.combatDebtChecks[0].actors[0];$row.actual.$Name=$Actual;$row.fields[$index].actual=$Actual;$v}
foreach($field in @('Standard','Move','Swift','Initiative','Reaction')){
 Check ('native Single upper-bound rounding is preserved '+$field) {$v=FloatField (Fresh) $field 1.0 1.001;Assert-KmcChunk7CombatDebtChecks $v.request $v.artifact.observations} $true
 Check ('native Single lower-bound rounding is preserved '+$field) {$v=FloatField (Fresh) $field 1.001 1.0;Assert-KmcChunk7CombatDebtChecks $v.request $v.artifact.observations} $true
}
foreach($fault in @('scenario','owned-case','checkpoint')){Check ('exact selector refuses singleton-array '+$fault){$v=Fresh;switch($fault){'scenario'{$v.request.scenario=@($v.request.scenario)};'owned-case'{$v.request.ownedPairs.case=@($v.request.ownedPairs.case)};'checkpoint'{$v.request.persistenceCase=@($v.request.persistenceCase)}};if(Test-KmcChunk7CombatDebtDiagnosticRequest $v.request){throw 'Array-valued wire identity selected a scalar native case.'}}}
foreach($name in @('kind','edge')){foreach($side in @('before','after','both')){Check ('native event refuses singleton-array '+$name+' '+$side){$v=Fresh;$d=$v.artifact.observations.coldRestoration.debtDiagnostics;$d.events=@((Event $v 'native-join-combat' 'before' 1),(Event $v 'native-join-combat' 'after' 1));if($side-cin@('before','both')){$d.events[0].$name=@($d.events[0].$name)};if($side-cin@('after','both')){$d.events[1].$name=@($d.events[1].$name)};Validate $v} $true}}
foreach($actual in @(1.0009,0.9991)){Check ('nearby native Single tolerance remains accepted '+$actual){$v=FloatField (Fresh) 'Standard' 1.0 $actual;Assert-KmcChunk7CombatDebtChecks $v.request $v.artifact.observations}}
$watch.Stop();$failed=@($results|Where-Object{-not$_.pass}).Count;$receipt=[pscustomobject]@{status=$(if($failed){'FAIL'}else{'PASS'});passed=($results.Count-$failed);failed=$failed;seconds=$watch.Elapsed.TotalSeconds;results=@($results);nativeInvoked=$false;buildInvoked=$false;scope='Actual private restoration reader and new closed diagnostic validators over existing generated five-actor fixture; no owner lineage facade/native source qualification or product/native proof.'}
[IO.File]::WriteAllText((Join-Path $OutputDirectory 'receipt.json'),($receipt|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false));Write-Output ('Debt diagnostic reader '+$receipt.passed+' PASS / '+$failed+' FAIL');if($failed){exit 1}
